INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES
('729b89f8-2662-40cb-a616-35173b87f72c', '21feff02-016d-46e2-bb9d-c27495133b1b', '85. óra: Projektóra', 'Családi költségvetés készítése megadott keretből, százalékos megoszlások számítása.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "25513a09-3676-4a7b-9a34-604e011b748d", "text": "Ha a család havi jövedelme 400 000 Ft, és 30%-ot költenek lakhatásra, hány Ft a lakhatási költség?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "120000"}, {"id": "bab7e54c-177c-4ede-aeb6-4ef2a0b844e0", "text": "Ha a jövedelem 40%-át élelmiszerre költik, hány Ft megy élelmiszerre? (400000 * 0,4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "160000"}, {"id": "763bcbbe-bdc4-4985-a466-8b2d6dcda4bd", "text": "Hány Ft marad megtakarításra és egyéb kiadásokra? (400000 - 120000 - 160000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "120000"}, {"id": "39fcee8a-ea3a-43d7-a2af-ac73346d6aa0", "text": "A családi költségvetés készítésekor a kiadások összege nem haladhatja meg a bevételeket.", "type": "true-false", "options": [{"id": "8ab6dbf9-9f57-4364-a86f-85434d7c90ee", "text": "Igaz", "isCorrect": true}, {"id": "c5863d39-e3b7-46e9-837b-4ba935b45fbb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "accff16a-fb4b-4934-b4d4-2c06f965f812", "text": "Hány százalékot tesz ki a megmaradt 120 000 Ft a 400 000 Ft-os jövedelemből?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "d49f3485-ee01-4bd2-a0b2-3d8ef043a3ca", "text": "A százalékos megoszlás kördiagramon ábrázolva jól szemlélteti a kiadások arányát.", "type": "true-false", "options": [{"id": "226971c5-bfd7-4998-a586-f8ae28bbd05a", "text": "Igaz", "isCorrect": true}, {"id": "e11d071c-3feb-4951-98b8-b77370e5f552", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "10c5b21b-1683-4325-a8da-05c3c293ca77", "text": "A tudatos pénzügyi tervezés segít elkerülni az eladósodást.", "type": "true-false", "options": [{"id": "cd5126a3-54e5-408c-8534-c2dcbce6d530", "text": "Igaz", "isCorrect": true}, {"id": "00600823-663f-4dbf-bb62-699d57438d82", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('6654b2db-4b48-4908-a614-449e5f282a52', '21feff02-016d-46e2-bb9d-c27495133b1b', '86. óra: Nyitott mondatok', 'Lebontogatás (visszafelé gondolkodás) és próbálgatás módszere egyenleteknél.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "f7e6fc9f-b3c5-413b-94cf-762f777335a8", "text": "Mit jelent a lebontogatás (visszafelé gondolkodás) módszere?", "type": "multiple-choice", "options": [{"id": "02f474fd-5e4b-4ea0-bc5a-4841d7a4ea98", "text": "A végeredményből kiindulva az inverz (ellentétes) műveleteket végezzük el visszafelé", "isCorrect": true}, {"id": "29497f26-b61a-4147-9eb4-e2f05deecb11", "text": "Visszafelé írjuk le a számokat", "isCorrect": false}, {"id": "13063127-2f97-4196-b0c3-eccbd2797a40", "text": "Tippelünk egy számot és feladjuk", "isCorrect": false}, {"id": "85c888b9-23c9-4351-9594-22ce816607bb", "text": "Kivonunk mindent 100-ból", "isCorrect": false}], "timeLimit": 15}, {"id": "b06f81d8-eb33-4094-9597-a4878ea37b14", "text": "Melyik szám teszi igazzá: 2 * x + 5 = 17? (17 - 5 = 12, 12 / 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "cdac3156-48b9-4333-b7b9-0e5e597f09dc", "text": "Melyik szám teszi igazzá: (y - 4) : 3 = 5? (5 * 3 = 15, 15 + 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "19"}, {"id": "5640b803-454a-4ddf-b58c-d15aa645a874", "text": "Az ellenőrzés során a kapott értéket behelyettesítjük az eredeti nyitott mondatba.", "type": "true-false", "options": [{"id": "ab91724d-5220-4d07-b703-769018a7bd9f", "text": "Igaz", "isCorrect": true}, {"id": "daa3d474-f1c8-4933-a70a-cceecd386913", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8b888d0d-8a05-4ff7-a5ab-e85288079f56", "text": "Melyik szám teszi igazzá: 3 * a - 10 = 20?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "14282246-a083-41d9-adb4-bf196f607e48", "text": "A próbálgatásos módszernél rendszerezett táblázatot érdemes vezetni.", "type": "true-false", "options": [{"id": "9b439ff7-3263-47e9-987a-17a749520e05", "text": "Igaz", "isCorrect": true}, {"id": "c8e61002-55f6-489c-95c7-00e652f37e43", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9c84b513-6541-4bb3-b1d1-c0191ec37418", "text": "Melyik szám teszi igazzá: x / 4 + 2 = 7?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}]'::jsonb, true, NOW()),
('112b140e-afbe-4cc0-84db-83a5bb72b05a', '21feff02-016d-46e2-bb9d-c27495133b1b', '87. óra: Feladatmegoldás: Nyitott mondatok', 'Gyakorlás: lebontogatási módszer alkalmazása egyenletek és egyenlőtlenségek megoldásában.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "b05cabae-73a4-435c-b27a-93d0f73b0418", "text": "Melyik szám teszi igazzá: 4 * (x + 2) = 36? (36/4 = 9, 9-2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "a71422fe-7944-4def-bffc-9362785dc7ee", "text": "Melyik szám teszi igazzá: 5 * y - 12 = 38? (50/5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "34d90653-9153-4950-a744-19315f784ad1", "text": "Ha az alaphalmaz a természetes számok (0, 1, 2, ...), hány megoldása van a 2 * x < 6 egyenlőtlenségnek? (x = 0, 1, 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "a212cf36-4ff1-4bc5-93a4-44ae3752f59c", "text": "Az egyenlőtlenségeknek több megoldása is lehet egy megadott alaphalmazon.", "type": "true-false", "options": [{"id": "85617496-5e65-4e88-a3a4-89974ba34d2b", "text": "Igaz", "isCorrect": true}, {"id": "d2eadfc9-2bde-4c1c-9455-130ea4a612d8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4b6aa7aa-2b26-4ad2-aaec-aacb416643d0", "text": "Melyik szám teszi igazzá: (z + 10) / 2 = 15?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "f676e68b-e9a7-4c3f-ba0a-55d57036118c", "text": "Ha az egyenletnek nincs megoldása az adott alaphalmazon, az igazsághalmaz az üres halmaz.", "type": "true-false", "options": [{"id": "6f2fcfd5-bf67-4329-ac38-c92de7a7c0b3", "text": "Igaz", "isCorrect": true}, {"id": "23e6fa15-8982-4e07-b42c-6851c768b31f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "06a50e78-193c-4277-9cf9-ec26b987b0d9", "text": "Melyik szám teszi igazzá: 10 * x - 25 = 75?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]'::jsonb, true, NOW()),
('720be285-52fa-40fc-a52a-21d600ade74b', '21feff02-016d-46e2-bb9d-c27495133b1b', '88. óra: Gyakorlóóra', 'Nyitott mondatok és műveleti sorrend gyakorlása.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "5e4f3d44-68bc-4b19-82ca-ef00db525b96", "text": "Melyik szám teszi igazzá: 3 * x + 7 = 34?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "00012f09-dd4b-4e0c-ac87-f28d49bf0838", "text": "Melyik szám teszi igazzá: (x - 5) * 6 = 42?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "c8a13677-786e-4bea-9cbe-392cc41df0d5", "text": "A lebontogatás lépései során az utolsóként elvégzett művelet inverzével kezdjük a számolást.", "type": "true-false", "options": [{"id": "ab8ce67e-6c0d-4180-95a1-1117e6ef439b", "text": "Igaz", "isCorrect": true}, {"id": "bb0bc5f5-8c99-44d7-bc86-ddddc30b5292", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1703fce6-d6e2-440e-a269-54a6233e9132", "text": "Mennyi x értéke, ha 50 - 2 * x = 30? (2x = 20)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "dab24287-2b65-44dc-8f5d-41a9bf19e7b7", "text": "Mennyi y értéke, ha y / 3 - 4 = 6?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "f9a54dd4-6a42-46be-bb5f-2a219f245277", "text": "Az ellenőrzés kihagyása növeli a hibázás kockázatát.", "type": "true-false", "options": [{"id": "48bf1e55-9b2b-4883-a1c7-34de0d40b705", "text": "Igaz", "isCorrect": true}, {"id": "9548f6e3-3fc7-414f-aa8d-a1f22cd25a65", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "cec07483-55a6-4ef7-a23c-45a8571bdffa", "text": "Melyik szám teszi igazzá: 8 * a + 4 = 68?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}]'::jsonb, true, NOW()),
('77ba5457-4d34-4a84-b40c-d55d383553a6', '21feff02-016d-46e2-bb9d-c27495133b1b', '89. óra: Szöveges feladatok', 'Szöveges feladatok megoldása nyitott mondatok felírásával, ábrakészítéssel.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "52f57411-e459-4618-9b30-b87d97778e61", "text": "Gondoltam egy számot, megszóroztam 3-mal, hozzáadtam 12-őt és 45-öt kaptam. Mi volt a szám? (3x + 12 = 45 -> 3x = 33)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}, {"id": "99d14b7b-66e1-452d-8d61-993a5db47461", "text": "Gondoltam egy számot, kivontam belőle 8-at, megszoroztam 4-gyel és 40-et kaptam. Mi volt a szám? ((x-8)*4 = 40 -> x-8 = 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "9aee4128-b30f-492c-b309-8767a8a1be14", "text": "Katinak 3-szor annyi matricája van, mint Petinek. Összesen 48 matricájuk van. Hány matricája van Petinek? (x + 3x = 48 -> 4x = 48)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "ae62919e-4ca9-47a7-b007-2f2dfe283d1e", "text": "Hány matricája van Katinak? (3 * 12)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "b081c2c3-a8a4-4c3c-9e64-8e1d28feff09", "text": "A szöveges feladatok megoldásának lépései: Értelmezés -> Adatok/Ismeretlen -> Nyitott mondat -> Számolás -> Ellenőrzés -> Válaszmondat.", "type": "true-false", "options": [{"id": "8ad506d6-db8a-472d-9916-a60809e5b94b", "text": "Igaz", "isCorrect": true}, {"id": "877724e5-cf34-49e2-8ff6-fa1270445617", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d80d8b9d-b94f-4ed3-9dd1-6750b280a5a5", "text": "Ha a feladatban a ''kétszer annyi'' kifejezés szerepel, 2-vel való szorzásra gondolunk.", "type": "true-false", "options": [{"id": "f902b11e-a492-421a-aac0-ee8aee2db188", "text": "Igaz", "isCorrect": true}, {"id": "488cf546-a657-4356-acc1-8f575ee27d44", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5d5a836b-a785-4a8c-aa47-7bcc7a8b4804", "text": "Gondoltam egy számot, elosztottam 5-tel, hozzáadtam 7-et és 12-őt kaptam. Mi a szám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}]'::jsonb, true, NOW()),
('47ed6d77-c4bb-45f2-aa9e-e7eff207e240', '21feff02-016d-46e2-bb9d-c27495133b1b', '90. óra: Gyakorlóóra', 'Matematikai szövegezésű feladatok gyakorlása, ábrakészítés, összefüggések.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "7577c780-b9cf-433c-bcd0-c5a80640872b", "text": "Apa 4 évvel idősebb, mint Anya. Életkoruk összege 76 év. Hány éves Anya? (2x + 4 = 76 -> 2x = 72)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "630c82d8-dedb-4302-91df-6ef1d26bbfd5", "text": "Hány éves Apa? (36 + 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "153862c1-91ca-4771-bd5d-d921bfd40b7c", "text": "Egy téglalap kerülete 40 cm. Hosszabbik oldala 4 cm-rel hosszabb a rövidebbnél. Hány cm a rövidebb oldal? (2*(x + x+4) = 40 -> 4x + 8 = 40)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "d960c467-63c1-47d5-940f-2ec3f1af29ad", "text": "Hány cm a hosszabbik oldal? (8 + 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "208c3407-cf86-41aa-bcf9-4b830fe82888", "text": "A szakaszos ábrázolás nagymértékben segít a szöveges feladatok összefüggéseinek megértésében.", "type": "true-false", "options": [{"id": "16355fde-05b5-483a-b0a4-1e8f4b0c9197", "text": "Igaz", "isCorrect": true}, {"id": "d8e6efb9-f1c7-4711-b7b0-07c1aba7ac51", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3d357ede-e0eb-442e-8a86-4020c86016b6", "text": "Három egymást követő egész szám összege 45. Mi a legkisebb szám? (x + x+1 + x+2 = 45 -> 3x + 3 = 45)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "14"}, {"id": "c7bf1ae1-67b2-4ecc-ae62-cc6ab0b41369", "text": "A válaszmondat felírása kötelező a szöveges feladat végén.", "type": "true-false", "options": [{"id": "e2069719-8c6e-480c-9db6-40f875b024ec", "text": "Igaz", "isCorrect": true}, {"id": "540499d2-02dd-42ca-8842-c899fccaddfa", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('16da4aa7-6188-4486-8766-886a31eaa7cd', '21feff02-016d-46e2-bb9d-c27495133b1b', '91. óra: Feladatmegoldás', 'Hétköznapi vásárlási, méréseket és egyenleteket tartalmazó szöveges feladatok.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "dce10e4a-cf1b-4853-ae41-829cee62ef6c", "text": "3 füzet és 1 toll összesen 1100 Ft-ba kerül. A toll ára 200 Ft. Hány Ft 1 füzet ára? (3x + 200 = 1100 -> 3x = 900)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "1a2695ea-7b30-4276-853f-c35bcc39e81b", "text": "Peti 2000 Ft-tal ment a boltba. Vett 3 kg narancsot 500 Ft/kg áron. Hány Ft visszajárót kapott? (2000 - 1500)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "500"}, {"id": "8c3059a7-4426-4b39-b2fb-766c5f0a45c7", "text": "Egy raktárban 120 láda gyümölcs van. Az első nap elvitték a 1/3-át, a második nap a megmaradt ládák felét. Hány láda maradt? (120 - 40 = 80, 80 - 40)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "e4cb9688-d248-4f02-8bb1-5b5759c8ccb5", "text": "A mindennapi életben sok probléma modellezhető egyenlettel.", "type": "true-false", "options": [{"id": "308cc099-4fb3-47d4-bbbc-b93058e302aa", "text": "Igaz", "isCorrect": true}, {"id": "d9610e19-faa5-4b77-8da8-26d9f31401f6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c81ccf20-79ba-478b-ad94-e9ea0962c2ff", "text": "Melyik egyenlet írja le: ''Egy szám 4-szeresénél 5-tel több a 25''? (4x + 5 = 25)", "type": "multiple-choice", "options": [{"id": "8e886beb-11cd-49ed-a09a-462b69a84197", "text": "4x + 5 = 25", "isCorrect": true}, {"id": "3cf042d9-c796-4f8c-a62b-71439382d177", "text": "x + 4 + 5 = 25", "isCorrect": false}, {"id": "1a554403-973e-427a-87b5-6f6cb97f3cce", "text": "4x - 5 = 25", "isCorrect": false}, {"id": "12e0ba8f-5f4e-42fc-9acc-2d5f9697c66b", "text": "x / 4 + 5 = 25", "isCorrect": false}], "timeLimit": 15}, {"id": "1171e4e3-65fe-4792-a883-c4d082e110bb", "text": "Mennyi a gondolt szám a 4x + 5 = 25 egyenletben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "3f8e0da4-fabe-40a4-88f6-e32727aa9138", "text": "Az ellenőrzést a feladat eredeti szövegébe való behelyettesítéssel végezzük.", "type": "true-false", "options": [{"id": "b6ae1e01-9df3-4c3f-b38a-9ddf6a245c41", "text": "Igaz", "isCorrect": true}, {"id": "ef1d9ff9-ca40-484c-880b-678283fe5b00", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('e8987b22-3baa-49e2-85ae-921ff45336b7', '21feff02-016d-46e2-bb9d-c27495133b1b', '92. óra: Több megoldás is lehet', 'Több megoldást megengedő szöveges feladatok és egyenlőtlenségek vizsgálata.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "67b28a7e-7999-4847-8d0a-281e17bec1fe", "text": "Katinak legfeljebb 10 Ft-ja lehet, és páros számú forintja van. Hányféle lehetséges összege lehet természetes számokban? (0, 2, 4, 6, 8, 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "9d140820-ff35-46ca-8921-a756c07214f1", "text": "Mely kifejezés jelenti azt, hogy ''legfeljebb 5''?", "type": "multiple-choice", "options": [{"id": "ce0f2da2-9b60-4d67-914b-48eb0a02d270", "text": "Kisebb vagy egyenlő, mint 5 (x <= 5)", "isCorrect": true}, {"id": "4cd86e87-c265-4ad3-92d4-586defecab05", "text": "Nagyobb, mint 5", "isCorrect": false}, {"id": "953b9906-d687-432b-b066-374c82fe92ed", "text": "Pontosan 5", "isCorrect": false}, {"id": "9c2c7df1-43c4-4edd-8538-d7f251a9c6cc", "text": "Legalább 5", "isCorrect": false}], "timeLimit": 15}, {"id": "cf413a27-02db-4794-8f81-d4d6dfdfefe3", "text": "Mely kifejezés jelenti azt, hogy ''legalább 5''?", "type": "multiple-choice", "options": [{"id": "60e6eaf9-6ff4-4a64-be6e-d654d488030f", "text": "Nagyobb vagy egyenlő, mint 5 (x >= 5)", "isCorrect": true}, {"id": "4b4828aa-12fb-4466-88e1-0c72d55f5b51", "text": "Kisebb, mint 5", "isCorrect": false}, {"id": "1fa7cd96-54b6-40b5-bbfb-f3dadb0290d2", "text": "Pontosan 5", "isCorrect": false}, {"id": "447f5d7c-55ad-4db5-b11f-b70e2f655ba2", "text": "Legfeljebb 5", "isCorrect": false}], "timeLimit": 15}, {"id": "0e293232-d62f-44f9-b0f0-4a2517b6b576", "text": "A ''legalább 3 és legfeljebb 6'' feltételnek eleget tevő egész számok száma: 3, 4, 5, 6 (összesen 4 szám).", "type": "true-false", "options": [{"id": "84234364-9fed-4ff6-b8e1-75e2cbd2f136", "text": "Igaz", "isCorrect": true}, {"id": "1cb795f6-b2a8-40e3-8d65-36064f37a550", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d4b67519-894b-45ec-8e19-574c077ef071", "text": "Hány természetes szám megoldása van a 2 * x <= 8 egyenlőtlenségnek? (x = 0, 1, 2, 3, 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "f93e20b3-f675-414a-b12a-17226f2f9c5b", "text": "A több megoldással rendelkező feladatoknál az összes megoldás megtalálása a cél.", "type": "true-false", "options": [{"id": "3ca91d89-cfd2-4e7d-b13e-7085f5553df6", "text": "Igaz", "isCorrect": true}, {"id": "0e90e182-bbec-4633-96f4-c0778d193ed4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "188044b2-d286-49e0-9c5a-26f3462f4fd8", "text": "Melyik legkisebb természetes szám teljesíti az x > 7 egyenlőtlenséget?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}]'::jsonb, true, NOW()),
('39891c5b-ac26-4da5-ad2b-7bdf7d710723', '21feff02-016d-46e2-bb9d-c27495133b1b', '93. óra: Létraverseny II.', 'Versenyszerű feladatmegoldás páros munkában a százalék és szöveges feladatok témakörében.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "01233298-f6be-4c2d-8b2f-13a8d1504e8e", "text": "Mennyi 1000 Ft-nak a 15%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "150"}, {"id": "d0bb3400-1afd-4055-9de5-e401683f2a2a", "text": "Melyik szám teszi igazzá: 2 * x + 10 = 50?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "5c73db65-49ce-4689-9837-6ee4576c976c", "text": "Ha 3 kg narancs 1200 Ft, mennyibe kerül 5 kg narancs?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "c42852e4-479e-42a8-9656-c16acb324d18", "text": "Hány százalék felel meg a 3/5 törtnek? (3/5 = 60/100)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "199a86ad-f3b5-417b-9757-ba7560488f56", "text": "Gondoltam egy számot, elosztottam 3-mal, hozzáadtam 4-et és 10-et kaptam. Mi a szám? ((10-4)*3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "aefd05cf-dd0c-4e49-a240-af66a1919bd3", "text": "A játékos feladványok erősítik az osztály közösségét és a matematikai önbizalmat.", "type": "true-false", "options": [{"id": "605f2453-b955-4a34-b911-19ded6122d36", "text": "Igaz", "isCorrect": true}, {"id": "fc2c1a54-961b-4010-bf8d-e6c52bc6a8f4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3904aa25-95e8-4958-8471-bdf9b6159963", "text": "Mennyi 400-nak a 25%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}]'::jsonb, true, NOW()),
('71f864a0-6d9c-43d7-beb2-f022d3353460', '21feff02-016d-46e2-bb9d-c27495133b1b', '94. óra: Összefoglalás', 'A fejezet fogalmainak (arány, egyenes arányosság, százalék, nyitott mondatok) összefoglalása.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "f628c0c2-7368-4cec-bfb5-f8a839811bdd", "text": "Mennyi a 8 : 24 arány egyszerűsített alakja?", "type": "multiple-choice", "options": [{"id": "241114f1-aca4-407e-b2bc-d4904970e7b5", "text": "1 : 3", "isCorrect": true}, {"id": "72294faf-d669-40aa-9a0d-21b13ae0e60f", "text": "1 : 4", "isCorrect": false}, {"id": "6425b433-de70-4f9b-b0e5-e89e1002bb04", "text": "2 : 3", "isCorrect": false}, {"id": "0d0b0ee8-9510-4be0-bdef-cb4180a149a2", "text": "3 : 1", "isCorrect": false}], "timeLimit": 15}, {"id": "afcfd2c4-8226-4dd5-ab8b-0b1369e79fdf", "text": "Hány százalék felel meg a 1/2-nek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "a1ca455a-d043-4004-b3f9-87543d31757f", "text": "Hány százalék felel meg a 1/5-nek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "a703f49a-8c29-4c55-9aa6-ae56221271d6", "text": "Mennyi 600 Ft-nak a 30%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "443db2ad-b716-48b0-a340-2a16fdd88a28", "text": "Melyik szám teszi igazzá: 4 * x - 8 = 32? (40/4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "3f4a8a9b-61a4-4907-9122-dc7c9540b80c", "text": "Az egyenes arányosság grafikonja az origóból induló félegyenes.", "type": "true-false", "options": [{"id": "43903630-a9e4-4306-a4fc-fa036843047f", "text": "Igaz", "isCorrect": true}, {"id": "28ace0bf-145b-4fa8-99f9-9cba31ca4526", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "11e21de2-722e-4f60-b1d8-dd54d181e49d", "text": "Mennyi 150-nek a 4/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "120"}]'::jsonb, true, NOW()),
('6c7bbac4-7cf3-4db1-8b2d-9e4c33e0a8be', '21feff02-016d-46e2-bb9d-c27495133b1b', '95. óra: Gyakorlóóra', 'Gyakorló feladatok önállóan, becslés és ellenőrzés.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "26fa4876-5e60-4c01-bc17-c92826ce4222", "text": "Egy 8000 Ft-os táska ára 25%-kal csökkent. Hány Ft a kedvezmény? (8000 * 0,25)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "ee5c7f09-cc3a-42ab-bc65-92bc938838a4", "text": "Mennyi a táska új ára? (8000 - 2000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6000"}, {"id": "fb98aad2-28a3-401b-8c96-dc8f6f979516", "text": "Melyik szám teszi igazzá: (x + 4) : 5 = 6?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "26"}, {"id": "75edba0f-79f1-48d6-ad69-54fc053ec57f", "text": "Ha 4 kg alma 1600 Ft, egyenes arányosság esetén 7 kg alma 2800 Ft-ba kerül.", "type": "true-false", "options": [{"id": "decf881f-07c3-43b5-9e03-c36645196838", "text": "Igaz", "isCorrect": true}, {"id": "2cded802-8584-48ae-b0c3-feadae1fd099", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ea053fd1-b532-40df-b69b-a49588f98a83", "text": "Mennyi 50-nek a 120%-a? (50 * 1,2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "a77afc3b-0cf5-4451-a701-9f5f4e804a62", "text": "Az ellenőrzés mindig megnyugtató visszajelzést ad a feladat helyességéről.", "type": "true-false", "options": [{"id": "096b5ddf-0087-4212-83d5-0f30b7baab44", "text": "Igaz", "isCorrect": true}, {"id": "f40457d2-6a57-47b9-aaa2-e1ae561265d6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "89a68067-a367-4b1d-8c6e-e7cebf9818da", "text": "Mennyi 1000-nek az 1%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]'::jsonb, true, NOW()),
